import{_ as n,C as l,o as i,c as s,a2 as d,b as c,w as r,a as o,E as u,a3 as m,j as a}from"./chunks/framework.CgxQ0r6v.js";const v=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_2.md"}'),p={name:"materias/Proyecto_Sociotecnologico_I/documentacion/I-III/Lectura_Catedra_Evaluacion_2.md"};function b(h,e,f,g,E,q){const t=l("Mermaid");return i(),s("div",null,[e[1]||(e[1]=d('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-trayecto-i" tabindex="-1">Materia: Proyecto Sociotecnológico (Trayecto I) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-trayecto-i" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico (Trayecto I)&quot;">​</a></h2><h3 id="eje-tematico-monitoreo-y-evaluacion-del-proyecto" tabindex="-1">Eje Temático: Monitoreo y Evaluación del Proyecto <a class="header-anchor" href="#eje-tematico-monitoreo-y-evaluacion-del-proyecto" aria-label="Permalink to &quot;Eje Temático: Monitoreo y Evaluación del Proyecto&quot;">​</a></h3><hr><h2 id="🧭-introduccion-midiendo-el-exito" tabindex="-1">🧭 Introducción: Midiendo el Éxito <a class="header-anchor" href="#🧭-introduccion-midiendo-el-exito" aria-label="Permalink to &quot;🧭 Introducción: Midiendo el Éxito&quot;">​</a></h2><p>Supongamos que ya terminaron de formatear todas las computadoras y dictaron los talleres de alfabetización tecnológica. Muchos estudiantes creen que aquí termina el proyecto y se van a casa a redactar el informe. Eso es un error fatal.</p><p>En la ingeniería de proyectos bajo el Enfoque del Marco Lógico (EML), la acción no basta; es imperativo <strong>comprobar objetivamente</strong> que la acción tuvo el resultado deseado. Si reparaste las computadoras pero al día siguiente los virus regresaron porque los usuarios conectaron pendrives infectados, tu proyecto no resolvió el problema central. Aquí entra el Monitoreo y la Evaluación.</p><hr><h2 id="🏛️-capitulo-i-diferencia-entre-monitoreo-y-evaluacion" tabindex="-1">🏛️ CAPÍTULO I: Diferencia entre Monitoreo y Evaluación <a class="header-anchor" href="#🏛️-capitulo-i-diferencia-entre-monitoreo-y-evaluacion" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Diferencia entre Monitoreo y Evaluación&quot;">​</a></h2><p>Aunque suenan similar, son dos procesos completamente diferentes, pero complementarios.</p><h3 id="_1-1-el-monitoreo-el-radar-en-tiempo-real" tabindex="-1">1.1 El Monitoreo (El Radar en Tiempo Real) <a class="header-anchor" href="#_1-1-el-monitoreo-el-radar-en-tiempo-real" aria-label="Permalink to &quot;1.1 El Monitoreo (El Radar en Tiempo Real)&quot;">​</a></h3><p>Es el seguimiento continuo que se hace <em>durante</em> la ejecución del proyecto. Sirve para ver si vamos respetando el cronograma y el presupuesto. <em>Analogía:</em> Es mirar el tablero del carro mientras conduces hacia tu destino para asegurarte de que tienes gasolina y no vas por encima del límite de velocidad. Si te quedas sin pasta térmica a mitad de semana, el monitoreo te obliga a hacer un ajuste presupuestario de emergencia.</p><h3 id="_1-2-la-evaluacion-el-veredicto-final" tabindex="-1">1.2 La Evaluación (El Veredicto Final) <a class="header-anchor" href="#_1-2-la-evaluacion-el-veredicto-final" aria-label="Permalink to &quot;1.2 La Evaluación (El Veredicto Final)&quot;">​</a></h3><p>Se realiza al final del proyecto (o de una fase muy importante). Su objetivo no es corregir, sino juzgar. Mide el impacto real de lo que hiciste. <em>Analogía:</em> Es llegar a tu destino y revisar cuánto dinero te quedó en el bolsillo y si el viaje valió la pena.</p><hr><h2 id="🧩-capitulo-ii-los-indicadores-la-regla-de-medir" tabindex="-1">🧩 CAPÍTULO II: Los Indicadores (La Regla de Medir) <a class="header-anchor" href="#🧩-capitulo-ii-los-indicadores-la-regla-de-medir" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Los Indicadores (La Regla de Medir)&quot;">​</a></h2><p>¿Cómo sabemos si el taller de Alfabetización fue un éxito? ¿Porque la gente sonrió y aplaudió? No. En ingeniería, todo debe medirse. Los <strong>Indicadores</strong> son las unidades de medida que nos dirán si cumplimos nuestro propósito.</p><h3 id="_2-1-caracteristicas-de-un-buen-indicador" tabindex="-1">2.1 Características de un Buen Indicador <a class="header-anchor" href="#_2-1-caracteristicas-de-un-buen-indicador" aria-label="Permalink to &quot;2.1 Características de un Buen Indicador&quot;">​</a></h3><p>Todo buen indicador debe ser cuantificable (números o porcentajes) e independiente.</p><ul><li>❌ <strong>Malo:</strong> &quot;Las computadoras están mejor que antes&quot;. (Es subjetivo y ambiguo).</li><li>✅ <strong>Bueno:</strong> &quot;El 100% de las computadoras del laboratorio (15 equipos) encienden y cargan el SO en menos de 2 minutos&quot;. (Es preciso y comprobable).</li></ul><h3 id="_2-2-medios-de-verificacion" tabindex="-1">2.2 Medios de Verificación <a class="header-anchor" href="#_2-2-medios-de-verificacion" aria-label="Permalink to &quot;2.2 Medios de Verificación&quot;">​</a></h3><p>Si afirmas que el indicador se cumplió, debes probarlo empíricamente. Los medios de verificación son las pruebas físicas.</p><ul><li><em>Indicador:</em> &quot;El 80% del personal aprobó el curso de LibreOffice&quot;.</li><li><em>Medio de Verificación:</em> Las pruebas escritas corregidas y firmadas por los asistentes. (Estas pruebas irán directo a los anexos de tu Informe Final).</li></ul><hr><h2 id="🏗️-capitulo-iii-control-de-calidad-del-soporte-tecnico" tabindex="-1">🏗️ CAPÍTULO III: Control de Calidad del Soporte Técnico <a class="header-anchor" href="#🏗️-capitulo-iii-control-de-calidad-del-soporte-tecnico" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Control de Calidad del Soporte Técnico&quot;">​</a></h2><p>En el ámbito estricto de la Informática Aplicada, el control de calidad es innegociable.</p><h3 id="_3-1-pruebas-de-estres-y-funcionalidad" tabindex="-1">3.1 Pruebas de Estrés y Funcionalidad <a class="header-anchor" href="#_3-1-pruebas-de-estres-y-funcionalidad" aria-label="Permalink to &quot;3.1 Pruebas de Estrés y Funcionalidad&quot;">​</a></h3><p>Antes de entregar formalmente la sala de computación a la directiva de la escuela o comunidad, deben realizar pruebas cruzadas:</p><ol><li><strong>Pruebas de Red:</strong> ¿Todas las PC pueden verse en la red local y hacer ping al router?</li><li><strong>Pruebas de Arranque:</strong> Reinicien todas las máquinas 3 veces seguidas para comprobar que el sistema operativo quedó estable.</li><li><strong>Control de Periféricos:</strong> Prueben cada teclado tecla por tecla, y cada mouse.</li></ol><h3 id="_3-2-diagrama-de-flujo-del-monitoreo" tabindex="-1">3.2 Diagrama de Flujo del Monitoreo <a class="header-anchor" href="#_3-2-diagrama-de-flujo-del-monitoreo" aria-label="Permalink to &quot;3.2 Diagrama de Flujo del Monitoreo&quot;">​</a></h3>',30)),(i(),c(m,null,{default:r(()=>[u(t,{id:"mermaid-114",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A(Inicio%20de%20Actividad)%20--%3E%20B%7B%C2%BFEst%C3%A1%20en%20el%20Cronograma%3F%7D%0A%20%20%20%20B%20--%20No%20--%3E%20C%5BDetener%20y%20Reprogramar%5D%0A%20%20%20%20B%20--%20S%C3%AD%20--%3E%20D%5BEjecutar%20Tarea%20T%C3%A9cnica%5D%0A%20%20%20%20%0A%20%20%20%20D%20--%3E%20E%5BRealizar%20Pruebas%20de%20Calidad%5D%0A%20%20%20%20E%20--%3E%20F%7B%C2%BFPas%C3%B3%20la%20prueba%3F%7D%0A%20%20%20%20F%20--%20No%20--%3E%20G%5BDiagnosticar%20Falla%20e%20Iterar%5D%0A%20%20%20%20G%20--%3E%20D%0A%20%20%20%20%0A%20%20%20%20F%20--%20S%C3%AD%20--%3E%20H%5BSolicitar%20Firma%20Comunitaria%5D%0A%20%20%20%20H%20--%3E%20I((Tarea%20Exitosa))%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e6f2ff%2Cstroke%3A%230066cc%0A%20%20%20%20style%20I%20fill%3A%23ccffcc%2Cstroke%3A%23009933%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("div",{class:"tip custom-block github-alert"},[a("p",{class:"custom-block-title"},"TIP"),a("p",null,[a("strong",null,"El Cierre Comunitario"),o(" Una vez que las métricas y los indicadores sean exitosos, deben redactar un "),a("strong",null,"Acta de Entrega de Equipos"),o(', detallando cuáles y cuántos equipos repararon. Esa acta debe ser firmada y sellada por la comunidad. Ese papel es "Oro" para ustedes en la UPSIT.')])],-1)),e[3]||(e[3]=a("p",null,[o("Ahora que tenemos las actas de entrega, las bitácoras y las pruebas listas, nos enfrentamos a la etapa académica por excelencia: compilar todo esto en "),a("strong",null,"El Informe Final"),o(".")],-1))])}const I=n(p,[["render",b]]);export{v as __pageData,I as default};
